#include "g++-2/stl_vector_shared.h"

class stringx { char *chars; void *my_buf; };
class hw_texture;
template<class T> class refptr { T *pointer; };

class vertex_context
{
public:
  enum clamp_mode_t { NOCLAMP, CLAMP_V, CLAMP_U, CLAMP_UV };
  enum alpha_mode_t { DESTALPHA, DESTCOLOR, INVDESTALPHA, INVDESTCOLOR, INVSRCALPHA, INVSRCCOLOR, SRCALPHA, SRCCOLOR, ONE, ZERO };
  enum cull_mode_t { CNONE, CCW, CW };
  vertex_context();
  ~vertex_context();
  void set_tex_clamp_mode(clamp_mode_t mode) { clamp_mode = mode; changed = true; }
  void set_src_alpha_mode(alpha_mode_t mode) { src_alpha = mode; changed = true; }
  void set_dst_alpha_mode(alpha_mode_t mode) { dst_alpha = mode; changed = true; }
  void set_punchthrough(bool puf) { punchthrough = puf; changed = true; }
  void set_fog(bool flag) { fog = flag; changed = true; }
  void set_translucent(bool) {}
  void set_specular(bool) {}
  void set_cull_mode(cull_mode_t mode) { cull_mode = mode; changed = true; }
private:
  hw_texture *texture;
  int filter_mode;
  clamp_mode_t clamp_mode;
  int flip_mode;
  alpha_mode_t src_alpha;
  alpha_mode_t dst_alpha;
  int shade_mode;
  cull_mode_t cull_mode;
  bool fog;
  bool changed;
  bool punchthrough;
};

enum
{
  TEX_ADDITIVE_ALPHA = 0x01,
  MAT_FULL_SELF_ILLUM = 0x02,
  MAT_NO_FOG = 0x04,
  MAT_ALLOW_ADDITIVE_LIGHT = 0x08,
  TEX_PUNCH_THROUGH = 0x10,
  TEX_CLAMP_U = 0x20,
  TEX_CLAMP_V = 0x40,
  MAT_BACKFACE_DEFAULT = 0x200,
  MAT_NO_BACKFACE_CULL = 0x400
};
enum { NGLBM_OPAQUE, NGLBM_PUNCHTHROUGH, NGLBM_BLEND, NGLBM_ADDITIVE };

class anim_texture
{
  stringx filename;
  vector<refptr<hw_texture> > frame_list;
  vector<vertex_context> vc_list;
  unsigned tex_flags;
  unsigned blend_mode;
  float blend_amount;
  unsigned diffuse_color;
public:
  hw_texture *get_texture(int frame) const;
  bool is_translucent() const;
  void process_vertex_contexts(unsigned mat_flags);
};

